<div class="card shadow-sm"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Data/hora</th><th>Integração</th><th>Fluxo</th><th>Operação</th><th>Estado</th><th>Registos</th><th>Duração</th><th>Mensagem</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><a href="?run=<?=$r['id']?>"><?=h($r['started_at'])?></a></td><td><?=h($r['integration_name'])?></td><td><?=h($r['flow_name']?:'Ligação')?></td><td><?=h($r['operation'])?><?=$r['dry_run']?' (simulação)':''?></td><td><span class="badge text-bg-<?=$r['status']==='success'?'success':($r['status']==='running'?'warning':'danger')?>"><?=h($r['status'])?></span></td><td><?=(int)$r['records_read']?> / <?=(int)$r['error_count']?> erros</td><td><?=(int)$r['duration_ms']?> ms</td><td><?=h($r['error_message']?:'—')?></td></tr><?php endforeach;?></tbody></table></div></div><a href="integrations.php" class="btn btn-link mt-3">Voltar</a>
